import type { Season, Source, Title } from './types'

/**
 * Offline sample catalog.
 *
 * The metadata below mirrors what cinejoy.pk shows publicly (TMDB identifiers,
 * posters and ratings) so the app looks and behaves like the real thing even
 * with no network. Playback uses public royalty-free demo streams — point the
 * app at the live feed (Settings → Live catalog) to resolve the real sources.
 */

/**
 * Bundled media. Every demo title plays from files generated by
 * `tools/make-sample-media.py`, so playback and the download manager work with
 * no external CDN — and identically inside the Android WebView.
 */
const DEMO_HLS = 'media/sample-hls/master.m3u8'
const DEMO_MP4_720 = 'media/sample-720.mp4'
const DEMO_MP4_540 = 'media/sample-540.mp4'
const DEMO_MP4_480 = 'media/sample-480.mp4'

function demoSources(seed: number): Source[] {
  // Rotate which rendition is "auto" so different titles feel like different encodes.
  const mp4Cycle = [DEMO_MP4_720, DEMO_MP4_540, DEMO_MP4_480, DEMO_MP4_720]
  const main = mp4Cycle[seed % mp4Cycle.length]
  return [
    { id: 'auto', label: 'Auto', url: DEMO_HLS, kind: 'hls' },
    { id: '1080p', label: '1080p', url: main, kind: 'mp4', quality: '1080p' },
    { id: '720p', label: '720p', url: DEMO_MP4_720, kind: 'mp4', quality: '720p' },
    { id: '480p', label: '480p', url: DEMO_MP4_480, kind: 'mp4', quality: '480p' },
  ]
}

function demoSeasons(seed: number, count: number, perSeason: number, still?: string): Season[] {
  return Array.from({ length: count }, (_, s) => ({
    number: s + 1,
    episodes: Array.from({ length: perSeason }, (_, e) => ({
      id: `${seed}-s${s + 1}e${e + 1}`,
      season: s + 1,
      number: e + 1,
      title: `Episode ${e + 1}`,
      runtime: `${38 + ((seed + e * 3) % 17)}m`,
      still,
      sources: demoSources(seed + s + e + 1),
    })),
  }))
}

