function seasonsFor(t: Title): Season[] {
  if (t.id === '96677') {
    const s1: Season = {
      number: 1,
      episodes: LUPIN_S1.map((e, i) => ({
        id: `96677-s1e${i + 1}`,
        season: 1,
        number: i + 1,
        title: e[0],
        runtime: e[1],
        overview: e[2],
        still: e[3],
        sources: demoSources(i + 1),
      })),
    }
    const rest: Season[] = [2, 3].map((n) => ({
      number: n,
      episodes: Array.from({ length: 8 }, (_, i) => ({
        id: `96677-s${n}e${i + 1}`,
        season: n,
        number: i + 1,
        title: `Episode ${i + 1}`,
        runtime: '45m',
        sources: demoSources(n * 10 + i),
      })),
    }))
    return [s1, ...rest]
  }
  return demoSeasons(Number(t.id) || 7, Math.min(t.seasonCount ?? 1, 3), 8, t.backdrop)
}

export const CATALOG: Title[] = seeds.map((s, i) => {
  const t: Title = {
    genres: [],
    ...s,
    demo: true,
    poster: s.poster,
    backdrop: s.backdrop || s.poster || 'media/poster.jpg',
    sources: s.type === 'movie' ? demoSources(i + 1) : undefined,
  } as Title
  if (t.type === 'series') t.seasons = seasonsFor(t)
  if (t.type === 'series' && !t.sources) {
    t.sources = t.seasons?.[0]?.episodes?.[0]?.sources
  }
  return t
})

